/**
 * This file defines the entire database schema (all enums and tables).
 *
 * Relations between these tables are defined separately in `relations.ts`
 * using Drizzle's `defineRelations()` API.
 *
 * After changing this file, create and apply a migration:
 * ```
 * npx drizzle-kit generate --name=<what_changed>
 * npx drizzle-kit migrate
 * ```
 * Only one teammate changes the schema at a time (pull first), or the
 * migrations will conflict.
 *
 * Conventions: snake_case in the database, camelCase in TypeScript. Ids are
 * uuids generated by Postgres. Every timestamp is a `timestamptz`.
 */

import { sql } from "drizzle-orm";
import {
  boolean,
  check,
  foreignKey,
  index,
  integer,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  unique,
  uuid,
} from "drizzle-orm/pg-core";
import { authUsers } from "drizzle-orm/supabase";
import {
  APPLICATION_KINDS,
  APPLICATION_PRIORITIES,
  APPLICATION_STATUSES,
  DOCUMENT_TYPES,
  LETTER_STATUSES,
} from "../models/enums";

/* ------------------------------------------------------------------ */
/* Shared column helpers                                               */
/* ------------------------------------------------------------------ */

/** A `timestamptz` column. Deadlines are compared in UTC and shown in local time. */
const timestamptz = (name: string) => timestamp(name, { withTimezone: true });

const createdAt = () => timestamptz("created_at").notNull().defaultNow();

/**
 * Drizzle sets this column on every `db.update(...)`. That is enough for us
 * because all writes go through the tRPC API; there is no database trigger.
 */
const updatedAt = () =>
  timestamptz("updated_at")
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

/* ------------------------------------------------------------------ */
/* Enums                                                               */
/* ------------------------------------------------------------------ */

export const applicationKindEnum = pgEnum(
  "application_kind",
  APPLICATION_KINDS,
);
export const applicationStatusEnum = pgEnum(
  "application_status",
  APPLICATION_STATUSES,
);
export const applicationPriorityEnum = pgEnum(
  "application_priority",
  APPLICATION_PRIORITIES,
);
export const letterStatusEnum = pgEnum("letter_status", LETTER_STATUSES);
export const documentTypeEnum = pgEnum("document_type", DOCUMENT_TYPES);

/* ------------------------------------------------------------------ */
/* Tables                                                              */
/* ------------------------------------------------------------------ */

/**
 * Defines the `profiles` table: one row per user.
 *
 * The row is created by a database trigger when Supabase Auth inserts into
 * `auth.users` (see the `auth_rls_storage` migration), so `id` is the auth
 * user's id and never generated here.
 */
export const profilesTable = pgTable("profiles", {
  id: uuid("id")
    .primaryKey()
    .references(() => authUsers.id, { onDelete: "cascade" }),
  displayName: text("display_name").notNull(),
  createdAt: createdAt(),
});

/**
 * Defines the `applications` table: one grad school or internship application.
 * Many applications belong to one profile (many-to-one).
 */
export const applicationsTable = pgTable(
  "applications",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: uuid("user_id")
      .notNull()
      .references(() => profilesTable.id, { onDelete: "cascade" }),
    kind: applicationKindEnum("kind").notNull(),
    /** School or company. */
    organization: text("organization").notNull(),
    /** Program name or role title. */
    position: text("position").notNull(),
    /** For example "Fall 2027" or "Summer 2027". */
    term: text("term"),
    status: applicationStatusEnum("status").notNull().default("researching"),
    priority: applicationPriorityEnum("priority"),
    /** Null for rolling deadlines. */
    deadlineAt: timestamptz("deadline_at"),
    /** Set the first time the status becomes `submitted`. */
    submittedAt: timestamptz("submitted_at"),
    portalUrl: text("portal_url"),
    location: text("location"),
    /** Stored in cents so money is never a floating-point number. */
    applicationFeeCents: integer("application_fee_cents"),
    notes: text("notes"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    check("applications_fee_non_negative", sql`${t.applicationFeeCents} >= 0`),
    // The list page and the dashboard both read "my applications by deadline".
    index("applications_user_deadline_idx").on(t.userId, t.deadlineAt),
  ],
);

/**
 * Defines the `recommenders` table: a person who writes letters for the user.
 * Many recommenders belong to one profile (many-to-one).
 */
export const recommendersTable = pgTable(
  "recommenders",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: uuid("user_id")
      .notNull()
      .references(() => profilesTable.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    email: text("email"),
    /** For example "Associate Professor". */
    title: text("title"),
    /** For example "UNC Computer Science". */
    organization: text("organization"),
    /** For example "Research advisor, 2 years". */
    relationship: text("relationship"),
    notes: text("notes"),
    /** Secret in the recommender portal link (`/r/[token]`). */
    shareToken: uuid("share_token").notNull().unique().defaultRandom(),
    /** The portal link only works while this is true. */
    shareEnabled: boolean("share_enabled").notNull().default(false),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("recommenders_user_idx").on(t.userId)],
);

/**
 * Defines the `recommendation_requests` table: one letter that one
 * recommender owes for one application.
 *
 * This is the join table of the many-to-many relationship between
 * applications and recommenders. It has its own id because each letter
 * carries data (status, dates, notes) and is edited on its own.
 */
export const recommendationRequestsTable = pgTable(
  "recommendation_requests",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    applicationId: uuid("application_id")
      .notNull()
      .references(() => applicationsTable.id, { onDelete: "cascade" }),
    recommenderId: uuid("recommender_id")
      .notNull()
      .references(() => recommendersTable.id, { onDelete: "cascade" }),
    status: letterStatusEnum("status").notNull().default("planned"),
    /** Set the first time the status becomes `requested`. */
    requestedAt: timestamptz("requested_at"),
    /** Null means "use the application's deadline". */
    dueAt: timestamptz("due_at"),
    /** Set when the status becomes `submitted`. */
    submittedAt: timestamptz("submitted_at"),
    notes: text("notes"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    // A recommender writes at most one letter per application.
    unique("recommendation_requests_application_recommender_unique").on(
      t.applicationId,
      t.recommenderId,
    ),
    index("recommendation_requests_recommender_idx").on(t.recommenderId),
  ],
);

/**
 * Defines the `documents` table: a logical document such as
 * "SOP - ML focus" or "Resume - SWE". The files live in `document_versions`.
 * Many documents belong to one profile (many-to-one).
 */
export const documentsTable = pgTable(
  "documents",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: uuid("user_id")
      .notNull()
      .references(() => profilesTable.id, { onDelete: "cascade" }),
    title: text("title").notNull(),
    type: documentTypeEnum("type").notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("documents_user_idx").on(t.userId)],
);

/**
 * Defines the `document_versions` table: one uploaded file.
 * Many versions belong to one document (many-to-one). A version is never
 * edited, so it has no `updated_at`.
 */
export const documentVersionsTable = pgTable(
  "document_versions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    documentId: uuid("document_id")
      .notNull()
      .references(() => documentsTable.id, { onDelete: "cascade" }),
    /** Assigned by the server: the document's current highest number + 1. */
    versionNumber: integer("version_number").notNull(),
    /** Object path in the private `documents` storage bucket. */
    storagePath: text("storage_path").notNull(),
    /** The original file name, shown in the UI and used for downloads. */
    fileName: text("file_name").notNull(),
    fileSizeBytes: integer("file_size_bytes"),
    /** For example "Shortened intro, added research section". */
    changeNote: text("change_note"),
    createdAt: createdAt(),
  },
  (t) => [
    unique("document_versions_document_version_unique").on(
      t.documentId,
      t.versionNumber,
    ),
  ],
);

/**
 * Defines the `application_documents` table: which exact file version was
 * attached to which application.
 *
 * This is the join table of the many-to-many relationship between
 * applications and document versions. It uses a **composite primary key**,
 * so the same version cannot be attached to the same application twice.
 */
export const applicationDocumentsTable = pgTable(
  "application_documents",
  {
    applicationId: uuid("application_id")
      .notNull()
      .references(() => applicationsTable.id, { onDelete: "cascade" }),
    documentVersionId: uuid("document_version_id").notNull(),
    attachedAt: timestamptz("attached_at").notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ columns: [t.applicationId, t.documentVersionId] }),
    // Declared here (not inline) only to give the constraint a readable name;
    // the generated one is too long for Postgres and gets replaced by a hash.
    foreignKey({
      name: "application_documents_version_fkey",
      columns: [t.documentVersionId],
      foreignColumns: [documentVersionsTable.id],
    }).onDelete("cascade"),
    index("application_documents_version_idx").on(t.documentVersionId),
  ],
);
